1	import { prisma } from '../lib/prisma'
2	import { Listing } from '../types/listing'
3	
4	export type ListingInput = {
5	  source: string
6	  listingUrl: string
7	  title: string | null
8	  price: string | null
9	  location: string | null
10	  imageUrl: string | null
11	}
12	
13	export async function getAllListings(): Promise<Listing[]> {
14	  return prisma.listing.findMany({
15	    orderBy: { seenAt: 'desc' },
16	  })
17	}
18	
19	export async function saveNewListings(
20	  listings: ListingInput[],
21	  savedSearchId?: string,
22	): Promise<{ saved: number; skipped: number; newListingIds: string[] }> {
23	  const newListingIds: string[] = []
24	  let saved = 0
25	  let skipped = 0
26	
27	  for (const listing of listings) {
28	    try {
29	      const created = await prisma.listing.create({
30	        data: {
31	          ...listing,
32	          savedSearchId: savedSearchId ?? null,
33	          priceObservations: listing.price
34	            ? { create: { price: listing.price } }
35	            : undefined,
36	        },
37	      })
38	      newListingIds.push(created.id)
39	      saved++
40	    } catch (error) {
41	      if (
42	        typeof error === 'object' &&
43	        error !== null &&
44	        'code' in error &&
45	        error.code === 'P2002'
46	      ) {
47	        skipped++
48	        await recordPriceChangeIfAny(listing)
49	      } else {
50	        throw error
51	      }
52	    }
53	  }
54	
55	  return { saved, skipped, newListingIds }
56	}
57	
58	// A re-scraped listing (matched by listingUrl) never overwrites history: the
59	// existing PriceObservation rows stay untouched, and a rescan only appends a
60	// new one when the price actually differs from the last-known price.
61	async function recordPriceChangeIfAny(listing: ListingInput): Promise<void> {
62	  if (!listing.price) {
63	    return
64	  }
65	
66	  const existing = await prisma.listing.findUnique({
67	    where: { listingUrl: listing.listingUrl },
68	  })
69	
70	  if (!existing || existing.price === listing.price) {
71	    return
72	  }
73	
74	  await prisma.$transaction([
75	    prisma.listing.update({
76	      where: { id: existing.id },
77	      data: { price: listing.price },
78	    }),
79	    prisma.priceObservation.create({
80	      data: { listingId: existing.id, price: listing.price },
81	    }),
82	  ])
83	}
